* { box-sizing: border-box; }
:root { --ink: #172554; --surface: #fff; --muted: #475569; --accent: #1d4ed8; --space: clamp(1rem, 3vw, 2rem); --radius: 1rem; }
body { margin: 0; color: var(--ink); background: #f8fafc; font: 1rem/1.65 system-ui, sans-serif; }
a { color: inherit; }
.site-header { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 1rem; padding: 1rem max(1rem, calc((100vw - 72rem) / 2)); background: var(--surface); }
.brand { font-weight: 800; text-decoration: none; }
.site-header nav { display: flex; flex-wrap: wrap; gap: 1rem; }
.page-shell { width: min(calc(100% - 2rem), 72rem); margin-inline: auto; }
.profile-hero { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(14rem, 0.8fr); gap: var(--space); align-items: center; padding-block: clamp(3rem, 8vw, 7rem); }
h1 { font-size: clamp(2.25rem, 5vw, 4.5rem); line-height: 1.05; letter-spacing: -0.04em; max-width: 12ch; }
.lead { max-width: 55ch; font-size: 1.2rem; }
.eyebrow { color: #1d4ed8; text-transform: uppercase; letter-spacing: .12em; font-size: .78rem; font-weight: 800; }
.profile-card, .contact-panel { padding: var(--space); border: 1px solid #cbd5e1; border-radius: var(--radius); background: var(--surface); }
.avatar { display: grid; place-items: center; width: 5rem; aspect-ratio: 1; border-radius: 50%; background: #dbeafe; color: #1e3a8a; font-size: 1.5rem; font-weight: 800; }
.section { padding-block: 2rem; }
.skill-list { display: flex; flex-wrap: wrap; gap: .75rem; padding: 0; list-style: none; }
.skill-list li { padding: .5rem .75rem; border-radius: 99px; background: #dbeafe; }
.button { display: inline-block; padding: .75rem 1rem; border-radius: .5rem; background: var(--accent); color: #fff; font-weight: 700; text-decoration: none; }
.site-footer { padding: 2rem 1rem; text-align: center; color: var(--muted); }
:focus-visible { outline: 3px solid #1d4ed8; outline-offset: 3px; }
@media (max-width: 42rem) { .profile-hero { grid-template-columns: 1fr; } .site-header { padding: 1rem; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; } }
